#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, a, b;
    cin >> n >> a >> b;

    if (a == 0 || b == 0) {
        cout << (n - 1) * (a + b);
        return 0;
    }

    map<long long, long long> mp;
    mp[0] = 1;
    --n;

    while (n > 0) {
        auto it = mp.begin();
        long long cost = it->first;
        long long cnt = it->second;
        long long erased = min(n, cnt);

        if (erased == cnt)
            mp.erase(it);
        else
            it->second -= erased;

        mp[cost + a] += erased;
        mp[cost + b] += erased;
        n -= erased;
    }

    long long ans = 0;
    for (const auto &[cost, cnt] : mp)
        ans += cost * cnt;

    cout << ans;
    return 0;
}

