#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

void printInt128(i128 x) {
    if (x == 0) {
        cout << 0;
        return;
    }
    if (x < 0) {
        cout << '-';
        x = -x;
    }
    string s;
    while (x > 0) {
        s.push_back(char('0' + x % 10));
        x /= 10;
    }
    reverse(s.begin(), s.end());
    cout << s;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n, a, b;
    cin >> n >> a >> b;

    if (a > b) swap(a, b);

    int64 remaining = n - 1;

    if (a == 0) {
        printInt128((i128)remaining * b);
        return 0;
    }

    int64 firstOther = (b - 1) / a + 1;
    if (remaining <= firstOther) {
        i128 q = remaining;
        i128 answer = q * (a + b) + (i128)a * q * (q - 1) / 2;
        printInt128(answer);
        return 0;
    }

    map<int64, int64> mp;
    mp[0] = 1;

    while (remaining > 0) {
        auto it = mp.begin();
        int64 cost = it->first;
        int64 count = it->second;
        int64 erased = min(remaining, count);

        if (erased == count)
            mp.erase(it);
        else
            it->second -= erased;

        mp[cost + a] += erased;
        mp[cost + b] += erased;
        remaining -= erased;
    }

    i128 answer = 0;
    for (const auto &[cost, count] : mp)
        answer += (i128)cost * count;

    printInt128(answer);
    return 0;
}

